// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/health", wrapper.GetApiV1Health)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/budgets", wrapper.GetApiV1Budgets)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/budgets", wrapper.PostApiV1Budgets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/budgets/{year}", wrapper.GetApiV1BudgetsYear)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/budgets/{year}", wrapper.PatchApiV1BudgetsYear)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/budgets/{year}/summary", wrapper.GetApiV1BudgetsYearSummary)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/items", wrapper.PostApiV1Items)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/items/{id}", wrapper.DeleteApiV1ItemsId)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/items/{id}", wrapper.PatchApiV1ItemsId)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/entries/{id}", wrapper.PatchApiV1EntriesId)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/entries/{id}/confirm", wrapper.DeleteApiV1EntriesIdConfirm)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entries/{id}/confirm", wrapper.PostApiV1EntriesIdConfirm)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/costs", wrapper.PostApiV1Costs)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/costs/{id}", wrapper.DeleteApiV1CostsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/costs/{id}", wrapper.GetApiV1CostsId)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/costs/{id}", wrapper.PatchApiV1CostsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/costs/{costId}/items", wrapper.GetApiV1CostsCostIdItems)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/costs/{costId}/items", wrapper.PostApiV1CostsCostIdItems)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/costs/{costId}/items/{id}", wrapper.DeleteApiV1CostsCostIdItemsId)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/costs/{costId}/items/{id}", wrapper.PatchApiV1CostsCostIdItemsId)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/costs/{costId}/items/{id}/confirm", wrapper.DeleteApiV1CostsCostIdItemsIdConfirm)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/costs/{costId}/items/{id}/confirm", wrapper.PostApiV1CostsCostIdItemsIdConfirm)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/goals", wrapper.GetApiV1Goals)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/goals", wrapper.PostApiV1Goals)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/goals/{id}", wrapper.DeleteApiV1GoalsId)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/goals/{id}", wrapper.PatchApiV1GoalsId)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/goals/{id}/contributions", wrapper.PostApiV1GoalsIdContributions)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/goals/{id}/contributions/{contributionId}", wrapper.DeleteApiV1GoalsIdContributionsContributionId)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/reserve-movements", wrapper.PostApiV1ReserveMovements)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/budgets/{year}/reserve-movements", wrapper.GetApiV1BudgetsYearReserveMovements)

	return m
}

